# === PRIOR END ===


@dataclass
class Candidate:
    segment: str
    target: str
    tariffs: tuple
    size: int                   # абонентов в кампании с учётом обрезки 5 000 по ID
    arpu_sum: float             # сумма predicted_arpu этих абонентов
    mu: float                   # оценка базового эффекта q (без множителя канала)
    sd: float
    pilots: list = field(default_factory=list)

    @property
    def key(self):
        return f"{self.segment}:{self.target}:{';'.join(self.tariffs)}"

    def lcb(self, k=RISK_K):
        return self.mu - k * self.sd

    def ucb(self, k=1.0):
        return self.mu + k * self.sd


class Agent:
    def __init__(self, verbose=True):
        self.verbose = verbose
        self.trace = []
        self._t0 = time.monotonic()

    # ------------------------------------------------------------------ public
    def act(self, env):
        self.trace = []
        self._t0 = time.monotonic()
        candidates = []
        try:
            profile = env.customer_profile
            candidates = self._make_candidates(profile, env)
            self._explore(env, candidates)
            plan = self._build_plan(candidates, env)
            plan = self._validate(plan, env)
        except Exception as exc:  # агент не должен падать: пилоты уже в зачёте
            self._log("error", error=f"{type(exc).__name__}: {exc}")
            plan = self._fallback_plan(candidates, env)
        if not plan:              # ТЗ: от 1 до 10 кампаний — пустой план не засчитывается
            try:
                plan = self._validate(self._minimal_campaign(candidates, env), env)
            except Exception as exc:
                self._log("minimal_error", error=f"{type(exc).__name__}: {exc}")
        self._log("done", campaigns=len(plan), seconds=round(time.monotonic() - self._t0, 1))
        return plan

    # ------------------------------------------------------------ 1-2: prior
    def _cell_prior(self, tariff, segment, target):
        """Оценка q до пилотов: (среднее, sd) в единицах q. sd = √(q_se² + TRANSFER_SD²)."""
        if PRIOR_FORMAT != EXPECTED_PRIOR_FORMAT:
            raise ValueError(f"Таблица PRIOR в формате {PRIOR_FORMAT}, агент ждёт {EXPECTED_PRIOR_FORMAT}: "
                             f"пересобери её через prior/build_prior.py")
        row = PRIOR.get((tariff, segment, target))
        if row is None:
            return None
        q, q_se, _n_obs = row
        sd = math.sqrt(q_se ** 2 + TRANSFER_SD ** 2)
        return PRIOR_SHRINK * q, sd

    def _make_candidates(self, profile, env):
        """
        Кандидат = однородная ячейка «текущий тариф × ARPU-сегмент → цель». В среде эффект одинаков
        для всех абонентов ячейки, поэтому пилот по ячейке — несмещённая оценка ровно того, что пойдёт
        в план (без переноса оценки смеси на её часть и без расхождения «среднее по людям / по ARPU»).
        Пока в кандидаты идут ячейки с положительной оценкой истории; разведка неизвестного — отдельный шаг.
        """
        known = profile.dropna(subset=["current_tariff", "arpu_segment"])
        cells = (known.groupby(["current_tariff", "arpu_segment"])["predicted_arpu"]
                 .agg(n="size", arpu_sum="sum").reset_index())
        targets = sorted(env.tariffs["tariff_plan_code"])
        candidates = []
        for cell in cells.itertuples(index=False):
            if cell.n < MIN_CANDIDATE_SIZE:
                continue
            for target in targets:
                if target == cell.current_tariff:
                    continue
                prior = self._cell_prior(cell.current_tariff, cell.arpu_segment, target)
                if prior is None or prior[0] <= 0:
                    continue
                candidates.append(Candidate(cell.arpu_segment, target, (cell.current_tariff,),
                                            int(cell.n), float(cell.arpu_sum), prior[0], prior[1]))
        candidates.sort(key=lambda c: (-c.mu * c.arpu_sum, c.key))
        self._log("candidates", count=len(candidates),
                  top=[(c.key, round(c.mu, 4), c.size) for c in candidates[:5]])
        return candidates

    @staticmethod
    def _audience(profile, segment, tariffs):
        seg = profile[(profile["arpu_segment"] == segment) & (profile["current_tariff"].isin(tariffs))]
        seg = seg.sort_values("ID_NUMBER").head(MAX_PER_CAMPAIGN)
        return len(seg), float(seg["predicted_arpu"].sum())

    # ----------------------------------------------------------- 3-4: pilots
    def _explore(self, env, candidates):
        channel = env.channels[PILOT_CHANNEL]
        m, cost = channel["conversion_multiplier"], channel["cost_per_contact"]
        while env.pilots_left > 0 and time.monotonic() - self._t0 < TIME_BUDGET_S:
            pool = [c for c in candidates
                    if len(c.pilots) < MAX_PILOTS_PER_CANDIDATE and c.ucb() > 0]
            if not pool:
                self._log("explore_stop", reason="нет кандидатов с положительной оптимистичной оценкой")
                break
            c = max(pool, key=lambda c: (c.ucb() * c.arpu_sum, c.key))
            n = min(PILOT_N_LARGE if c.size >= SMALL_SEGMENT else PILOT_N_SMALL, c.size)
            if n * cost > env.remaining_budget or n > env.remaining_contacts:
                self._log("explore_stop", reason="не хватает бюджета или охвата на пилот")
                break
            spent_budget = env.total_budget - env.remaining_budget
            spent_contacts = env.max_total_contacts - env.remaining_contacts
            if (spent_budget + n * cost > EXPLORE_BUDGET_SHARE * env.total_budget
                    or spent_contacts + n > EXPLORE_CONTACT_SHARE * env.max_total_contacts):
                self._log("explore_stop", reason="резерв ресурсов под финальный план",
                          spent_budget=spent_budget, spent_contacts=spent_contacts)
                break
            try:
                res = env.run_pilot(target_tariff=c.target, channel=PILOT_CHANNEL, n_customers=n,
                                    filter_arpu_segment=c.segment,
                                    filter_current_tariff=";".join(c.tariffs))
            except (RuntimeError, ValueError) as exc:
                self._log("pilot_error", candidate=c.key, error=str(exc))
                break
            self._update(c, res["observed_lift_ratio"], m, res["n_customers"])
            self._log("pilot", candidate=c.key, channel=PILOT_CHANNEL, n=res["n_customers"],
                      observed=round(res["observed_lift_ratio"], 4),
                      mu=round(c.mu, 4), sd=round(c.sd, 4), lcb=round(c.lcb(), 4))

    @staticmethod
    def _update(c, observed_ratio, multiplier, n):
        q_hat = observed_ratio / multiplier
        obs_sd = PILOT_NOISE_SD / (multiplier * math.sqrt(n))
        prec = 1 / c.sd ** 2 + 1 / obs_sd ** 2
        c.mu = (c.mu / c.sd ** 2 + q_hat / obs_sd ** 2) / prec
        c.sd = math.sqrt(1 / prec)
        c.pilots.append({"observed": observed_ratio, "n": n})

    # ------------------------------------------------------------- 5-6: plan
    def _build_plan(self, candidates, env, require_pilot=True):
        """
        План из подтверждённых ячеек (нижняя граница оценки > 0, есть пилот).
        Каждой ячейке «тариф × сегмент» — одна лучшая цель: второй контакт стоит денег, а эффект не удваивает.
        Ячейки с одинаковыми сегментом и целью объединяются в одну кампанию (оценка у каждой своя).
        Кампании — по убыванию ценности Σ (μ − K·σ) × ARPU, не больше 10.
        """
        viable = [c for c in candidates if c.lcb() > 0 and (c.pilots or not require_pilot)]
        best_per_cell = {}
        for c in sorted(viable, key=lambda c: (-c.lcb() * c.arpu_sum, c.key)):
            best_per_cell.setdefault((c.tariffs[0], c.segment), c)
        groups = {}
        for c in best_per_cell.values():
            groups.setdefault((c.segment, c.target), []).append(c)
        ranked = sorted(groups.items(), key=lambda kv: (-sum(c.lcb() * c.arpu_sum for c in kv[1]), kv[0]))
        plan = []
        budget, contacts = env.remaining_budget, env.remaining_contacts
        sms_cost = env.channels["sms"]["cost_per_contact"]
        for (segment, target), cells in ranked[:MAX_CAMPAIGNS]:
            tariffs = tuple(sorted(c.tariffs[0] for c in cells))
            size, _ = self._audience(env.customer_profile, segment, tariffs)
            size = min(size, contacts)
            if size <= 0:
                break
            channel = "sms" if size * sms_cost <= budget else "push"
            budget -= size * env.channels[channel]["cost_per_contact"]
            contacts -= size
            plan.append({"campaign_name": f"{segment}_{target}_{len(plan) + 1}",
                         "filter_arpu_segment": segment,
                         "filter_current_tariff": ";".join(tariffs),
                         "target_tariff": target, "channel": channel})
            self._log("plan_add", campaign=f"{segment}:{target}", channel=channel, contacts=size,
                      cells=[(c.tariffs[0], round(c.mu, 4), round(c.lcb(), 4), len(c.pilots)) for c in cells])
        return plan

    def _minimal_campaign(self, candidates, env):
        """
        Ни одна кампания не прошла порог надёжности, но ТЗ требует хотя бы одну.

        Единица оценки — однородная ячейка (текущий тариф × ARPU-сегмент → цель): в среде эффект
        одинаков для всех её абонентов, поэтому подгруппа ячейки по трафику и звонкам имеет тот же
        эффект — оценка переносится корректно. Оценку смеси тарифов на подгруппу НЕ переносим:
        для ячейки берём апостериор пилота, если пилот был ровно по этой ячейке, иначе априор истории.

        Цель запасной кампании — выполнить ТЗ с минимальным риском, а не заработать. Порядок выбора:
          1) минимальный убыток на нижней границе D = Σ predicted_arpu × множитель push × max(0, −(μ − K·σ));
          2) минимальный охват (Σ predicted_arpu подгруппы): оценка без пилота может не подтвердиться;
          3) при полном равенстве — больший ожидаемый эффект.
        """
        estimates = {}
        for key in PRIOR:
            prior = self._cell_prior(*key)
            if prior is not None:
                estimates[key] = (prior[0], prior[1], "априор истории")
        for c in candidates:               # пилот ровно по одной ячейке — его оценка точнее априора
            if c.pilots and len(c.tariffs) == 1:
                estimates[(c.tariffs[0], c.segment, c.target)] = (c.mu, c.sd, f"пилот ×{len(c.pilots)}")
        multiplier = env.channels[FALLBACK_CHANNEL]["conversion_multiplier"]
        profile = env.customer_profile.dropna(subset=["current_tariff", "arpu_segment", "data_segment"])
        groups = (profile.groupby(["current_tariff", "arpu_segment", "data_segment", "call_segment"])
                  ["predicted_arpu"].agg(size="size", arpu_sum="sum").reset_index())
        options = []
        for g in groups.itertuples(index=False):
            for (tariff, segment, target), (mu, sd, source) in estimates.items():
                if tariff != g.current_tariff or segment != g.arpu_segment or target == tariff:
                    continue
                if g.size > env.remaining_contacts:
                    continue
                downside = g.arpu_sum * multiplier * max(0.0, -(mu - FALLBACK_RISK_K * sd))
                gain = g.arpu_sum * multiplier * mu
                options.append((downside, g.arpu_sum, -gain,
                                f"{tariff}:{segment}:{target}:{g.data_segment}:{g.call_segment}",
                                g, target, mu, sd, source))
        if not options:
            self._log("minimal_skip", reason="нет ячейки с оценкой, которая помещается в остаток охвата")
            return []
        downside, exposure, neg_gain, key, g, target, mu, sd, source = min(options, key=lambda o: o[:4])
        self._log("minimal_campaign", cell=key, contacts=int(g.size), channel=FALLBACK_CHANNEL,
                  mu=round(mu, 4), sd=round(sd, 4), estimate=source,
                  downside=round(downside, 2), exposure_arpu=round(exposure, 2), expected_gain=round(-neg_gain, 2),
                  reason="ни одна кампания не прошла порог надёжности; ТЗ требует хотя бы одну. "
                         "Выбрана однородная ячейка с минимальным убытком на нижней границе и минимальным охватом")
        return [{"campaign_name": f"minimal_{g.arpu_segment}_{target}",
                 "filter_arpu_segment": g.arpu_segment, "filter_current_tariff": g.current_tariff,
                 "filter_data_segment": g.data_segment, "filter_call_segment": g.call_segment,
                 "target_tariff": target, "channel": FALLBACK_CHANNEL}]

    # ------------------------------------------------------ 7: checks + fallback
    def _validate(self, plan, env):
        tariffs = set(env.tariffs["tariff_plan_code"])
        ok = []
        for camp in plan:
            listed = camp.get("filter_current_tariff", "").split(";")
            if (camp["target_tariff"] in tariffs and camp["channel"] in env.channels
                    and camp.get("filter_arpu_segment") in SEGMENTS and all(t in tariffs for t in listed)
                    and camp.get("filter_data_segment", DATA_SEGMENTS[0]) in DATA_SEGMENTS
                    and camp.get("filter_call_segment", CALL_SEGMENTS[0]) in CALL_SEGMENTS):
                ok.append(camp)
            else:
                self._log("plan_drop", campaign=camp, reason="невалидная кампания")
        return ok[:MAX_CAMPAIGNS]

    def _fallback_plan(self, candidates, env):
        try:
            return self._validate(self._build_plan(candidates, env), env)
        except Exception as exc:
            self._log("fallback_error", error=f"{type(exc).__name__}: {exc}")
            return []

    # ------------------------------------------------------------------ trace
    def _log(self, kind, **data):
        entry = {"t": round(time.monotonic() - self._t0, 2), "kind": kind, **data}
        self.trace.append(entry)
        if self.verbose:
            print(f"[agent] {kind}: " + ", ".join(f"{k}={v}" for k, v in data.items()))
